using Microsoft.AspNetCore.Diagnostics;using Microsoft.AspNetCore.Mvc;using SchoolERP.Api.Logging;namespace SchoolERP.Api.Middleware;public sealed class UnhandledExceptionHandler(ILogger<UnhandledExceptionHandler> logger):IExceptionHandler{public async ValueTask<bool>TryHandleAsync(HttpContext c,Exception ex,CancellationToken ct){var correlation=c.Items[CorrelationIdMiddleware.ItemKey]?.ToString();logger.LogError(LoggingEventIds.Infrastructure.UnhandledException,ex,"Unhandled request exception for {Method} {Path}. CorrelationId {CorrelationId} RequestId {RequestId}",c.Request.Method,c.Request.Path.Value,correlation,c.TraceIdentifier);c.Response.StatusCode=500;await c.Response.WriteAsJsonAsync(new ProblemDetails{Status=500,Title="An unexpected error occurred.",Extensions={{"correlationId",correlation},{"requestId",c.TraceIdentifier}}},ct);return true;}}
